// @ai-rules:
// 1. [Constraint]: Runs in the `apply` job on DEFAULT-BRANCH code with the bot + Jira tokens. Never run PR code.
// 2. [Constraint]: Patches are data. gatePatch() applies them to a temp index and gates the resulting tree.
// 3. [Constraint]: Push/Jira failures must never prevent the summary comment.
// 4. [Gotcha]: The fix job's verdicts arrive as job outputs (env); PR code cannot forge them.

import { existsSync, readFileSync, statSync } from 'node:fs';
import { join } from 'node:path';

import { Octokit } from '@octokit/rest';

import { upsertComment } from '../github-comments';
import { getRepoContext } from '../shared/actions-context';
import { getLocalOwnersPath } from '../shared/owners';
import { requireEnv, safeErrorMessage } from '../utils';
import { assertTriggerTrusted, authEnv, gatePatch, git } from './gate';
import { runJira } from './jira';
import type { PolicyContext } from './policy';

const MARKER = '<!-- pr-autofix -->';
const root = process.env.GITHUB_WORKSPACE ?? process.cwd();
const ID = 'kubevirt-plugin-bot';
const BOT = ['-c', `user.name=${ID}`, '-c', `user.email=${ID}@users.noreply.github.com`];

const readPatch = (dir: string, file: string): string => {
  const path = join(dir, file);
  return existsSync(path) && statSync(path).size <= 1024 * 1024 ? readFileSync(path, 'utf8') : '';
};

/** Patches to try, best first: the AI patch only when verified, then the lint-only fallback. */
const candidates = (dir: string): Array<{ file: string; label: string }> => {
  const { AI_STATUS: ai, AI_VERIFY: verify } = process.env;
  const lint = readPatch(dir, 'lint.patch');
  const aiPatch = ai === 'ok' && verify === 'success' ? readPatch(dir, 'ai.patch') : '';
  return [
    { file: 'ai.patch', label: 'AI-assisted', text: aiPatch === lint ? '' : aiPatch },
    { file: 'lint.patch', label: 'lint-only', text: lint },
  ].filter(({ text }) => text.trim() !== '');
};

/** Why AI fixes did or did not contribute, from the fix job's verdicts. */
const aiNotes = (): string[] => {
  const { AI_STATUS: ai = '', AI_VERIFY: verify = '', TRUSTED: trusted } = process.env;
  if (trusted !== 'true') return ['AI fixes skipped: the PR author is not listed in OWNERS.'];
  if (ai === 'ok') return verify === 'success' ? [] : ['AI patch failed verification; discarded.'];
  return ai && ai !== 'skipped' ? [`AI fixes unavailable (${ai}).`] : [];
};

const summary = (code: string, jira: string[], notes: string[], runUrl: string): string => {
  const list = (items: string[], empty: string): string =>
    items.length ? items.map((item) => `\n  - ${item}`).join('') : empty;
  return [
    '### PR Autofix',
    `- **Commit:** ${code}`,
    `- **Jira:** ${list(jira, 'no changes needed')}`,
    `- **Remaining / skipped:** ${list(notes, 'none')}`,
    `\n[Run details](${runUrl})`,
  ].join('\n');
};

type Pr = Awaited<ReturnType<Octokit['pulls']['get']>>['data'];
type FixOptions = { botToken: string; prNumber: number; runUrl: string };

const none = (...notes: string[]) => ({ code: 'none pushed', notes });

/** Gate and push the best patch. Returns the commit description and notes for the summary. */
const fixCode = async (pr: Pr, ctx: PolicyContext, opts: FixOptions) => {
  const { FIX_RESULT: fix, HEAD_SHA: headSha, LINT_VERIFY: lintVerify } = process.env;
  if (fix !== 'success') return none(`The fix job ${fix ?? 'did not run'}.`);
  if (headSha !== pr.head.sha) return none('The PR head changed during the run; rerun `/autofix`.');
  const notes = aiNotes();
  const dir = process.env.RESULT_DIR ?? '';
  const patches = candidates(dir);
  if (patches.length === 0) return none(...notes, 'Nothing to fix automatically.');

  const ref = `refs/pull/${opts.prNumber}/head`;
  git(root, ['fetch', '--no-tags', '--depth=1', 'origin', ref], {
    env: authEnv(requireEnv('GITHUB_TOKEN')),
  });
  for (const { file, label } of patches) {
    const gated = gatePatch(pr.head.sha, join(dir, file), ctx);
    if (gated.problems.length > 0) {
      notes.push(`${label} patch rejected: ${gated.problems.slice(0, 3).join('; ')}`);
      continue;
    }
    const message = `autofix: ${label} fixes\n\nGenerated by /autofix: ${opts.runUrl}\n\nPR-Autofix: ${label}\n`;
    const commit = ['commit-tree', gated.tree, '-p', pr.head.sha, '-m', message];
    const sha = git(root, [...BOT, ...commit]).trim();
    try {
      const target = `https://github.com/${pr.head.repo?.full_name ?? ''}.git`;
      const push = ['push', target, `${sha}:refs/heads/${pr.head.ref}`];
      git(root, push, { env: authEnv(opts.botToken) });
      if (label === 'lint-only' && lintVerify !== 'success') {
        notes.push('ESLint or related tests still fail after the lint fixes.');
      }
      return { code: `\`${sha.slice(0, 7)}\` (${label})`, notes };
    } catch (err) {
      notes.push(`Could not push the ${label} patch (fork/no access?): ${safeErrorMessage(err)}`);
      break;
    }
  }
  return none(...notes);
};

const main = async (): Promise<void> => {
  const { owner, repo } = getRepoContext();
  assertTriggerTrusted(getLocalOwnersPath());
  const botToken = process.env.BOT_TOKEN || requireEnv('GITHUB_TOKEN');
  const octokit = new Octokit({ auth: botToken });
  const prNumber = Number(requireEnv('PR_NUMBER'));
  const { data: pr } = await octokit.pulls.get({ owner, pull_number: prNumber, repo });
  if (pr.state !== 'open') {
    console.log(`PR #${prNumber} is ${pr.state}; nothing to do.`);
    return;
  }
  const { data: head } = await octokit.repos.getCommit({ owner, ref: pr.head.sha, repo });
  const bots = [head.author?.login, head.committer?.login];
  const ctx: PolicyContext = {
    headIsBot:
      bots.some((name) => name?.endsWith('[bot]')) ||
      head.commit.message.includes('\nPR-Autofix: '),
    labels: pr.labels.map((label) => label.name),
    state: pr.state,
  };
  const runUrl = process.env.RUN_URL ?? '';
  const { code, notes } = await fixCode(pr, ctx, { botToken, prNumber, runUrl }).catch(
    (err: unknown) => none(`Autofix error: ${safeErrorMessage(err)}`),
  );

  const jira = await runJira(octokit, {
    baseBranch: pr.base.ref,
    owner,
    prNumber,
    repo,
    title: pr.title,
  }).catch((err: unknown) => [`Jira update failed: ${safeErrorMessage(err)}`]);
  await upsertComment(octokit, owner, repo, prNumber, MARKER, summary(code, jira, notes, runUrl));
};

if (require.main === module) {
  main().catch((err: unknown) => {
    console.error(`::error::${safeErrorMessage(err)}`);
    process.exit(1);
  });
}
